import os,re
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
inp,out=G['Demo pair 1 input'],G['Demo pair 1 output']
# input: left block 7s (9 cols), divider 9, right block 4s (9 cols). output 19x9: zeros where left had 0? check
mism=[]
for i in range(19):
    for j in range(9):
        pred=0 if inp[i][j]==0 else 2
        if pred!=out[i][j]: mism.append((i,j,inp[i][j],out[i][j]))
print(len(mism), mism[:20])

for k in ['Demo pair 1 input','Demo pair 2 input']:
    g,o=G[k],G[k.replace('input','output')]
    w=(len(g[0])-1)//2
    for i in range(len(g)):
        for j in range(w):
            a,b=g[i][j],g[i][w+1+j]
            if a==0 and b==0: print(k,i,j,'bothzero out',o[i][j])
# also check: any output cell value other than 0/2?
vals=set(v for o in [G['Demo pair 1 output'],G['Demo pair 2 output']] for r in o for v in r)
print(vals)
